import hashlib
import numpy as np
from typing import List

from indexify_extractor_sdk import ExtractorSchema, EmbeddingSchema
from indexify_extractor_sdk.base_embedding import (
    BaseEmbeddingExtractor,
    EmbeddingInputParams,
)


class IdentityHashEmbedding(BaseEmbeddingExtractor):
    """
    Implements a Hash Extractor, which can be used to find duplicates within the dataset.
    It hashes the text into bytes, and interprets these are a numpy array.

    We can extend this by LocalitySensitiveHashing, to also account for small perturbations in the input bytes.

    This is equivalent to an identity mapping (with the sample-size n large enough, there will be collisions, but this is highly unlikely )
    """

    def __init__(self):
        super(IdentityHashEmbedding, self).__init__(max_context_length=128)

    def extract_embeddings(self, texts: List[str]) -> List[List[float]]:
        return [self._embed(text) for text in texts]

    def extract_query_embeddings(self, query: str) -> List[float]:
        return self._embed(query)

    def schemas(self) -> ExtractorSchema:
        return ExtractorSchema(
            features={
                "embedding": EmbeddingSchema(distance_metric="cosine", dim=32)
            },
        )

    def _embed(self, text) -> List[float]:
        model = hashlib.sha256()
        model.update(bytes(text, "utf-8"))
        out = model.digest()
        return np.frombuffer(out, dtype=np.int8).tolist()

import json
import unittest
from typing import Type

from indexify_extractor_sdk.base_embedding import EmbeddingInputParams
from indexify_extractor_sdk.base_extractor import Content, Extractor, ExtractorSchema
from mpnet_base_v2 import MPNetV2
from parameterized import parameterized


class TestColBERTv2Base(unittest.TestCase):
    def __init__(self, *args, **kwargs):
        super(TestColBERTv2Base, self).__init__(*args, **kwargs)

    @parameterized.expand([("mpnetv2", MPNetV2())])
    def test_ctx_embeddings(self, extractor_name: str, extractor: Type[Extractor]):
        embeddings = extractor.extract(
            [Content.from_text("hello world")],
            EmbeddingInputParams(),
        )
        embeddings_values = json.loads(embeddings[0][0].feature.value)
        self.assertEqual(len(embeddings), 1)
        self.assertEqual(embeddings[0][0].feature.feature_type, "embedding")
        self.assertEqual(len(embeddings_values), 768)

    @parameterized.expand([("mpnetv2", MPNetV2())])
    def test_query_embeddings(self, extractor_name: str, extractor: Type[Extractor]):
        embeddings = extractor.extract_query_embeddings("hello world")
        self.assertEqual(len(embeddings), 768)

    @parameterized.expand([("mpnetv2", MPNetV2())])
    def test_extractor_info(self, extractor_name: str, extractor: Type[Extractor]):
        schema: ExtractorSchema = extractor.schemas()
        self.assertIsNotNone(schema.model_dump()["output_schemas"]["embedding"])


if __name__ == "__main__":
    unittest.main()

