    embedding_input_params = EmbeddingInputParams()
    contents = [Content.from_text(text="Hello World")]
    print(extractor.extract(contents, embedding_input_params))

from typing import (
    Any,
    Optional,
)


class RequestState:
    """Abstract interface for request state key-value API.

    The API allows to set and get key-value pairs from Indexify functions.
    The key-value pairs are scoped per Graph request.
    Each new request starts with an empty state (empty set of key-value pairs).
    A value can be any serializable object, the serializer of the current function
    is used to serialize and deserialize values."""

    def set(self, key: str, value: Any) -> None:
        """Set a key-value pair.

        Raises Exception if an error occurred."""
        raise NotImplementedError()

    def get(self, key: str, default: Optional[Any] = None) -> Optional[Any]:
        """Get a value by key. If the key does not exist, return the default value.

        Raises Exception if an error occurred."""
        raise NotImplementedError()

    def timer(self, name: str, value: float):
        raise NotImplementedError()

    def counter(self, name: str, value: int = 1):
        raise NotImplementedError()


class RequestProgress:
    """Abstract interface for reporting graph request progress."""

    def update(self, current: float, total: float) -> None:
        """Update the progress of the current task execution.

        Args:
            current: Current progress value
            total: Total progress value
        """
        raise NotImplementedError()


class RequestContext:
    """Abstract interface for request context."""

    @property
    def request_id(self) -> str:
        raise NotImplementedError()

    @property
    def state(self) -> RequestState:
        raise NotImplementedError()

    @property
    def progress(self) -> RequestProgress:
        raise NotImplementedError()


class RequestContextPlaceholder(RequestContext):
    """A placeholder used by user code in place of RequestContext when calling a @tensorlake_function.

    Inherits from RequestContext just to show explicitly that it can be passed into a function call
    instead of an actual RequestContext instance. Must be serializable by any user serializer because
    this object is stored in user args and kwargs.
    """

    def __eq__(self, value):
        # A placeholder is equal to any other placeholder.
        # This allows to easily compare function calls in tests.
        return isinstance(self, RequestContextPlaceholder) and isinstance(
            value, RequestContextPlaceholder
        )

from flask import Flask, request, jsonify, render_template
from flask_cors import cross_origin

app = Flask(__name__)

# Hello API for testing purposes
@app.route('/hello', methods=['GET'])
@cross_origin()
def hello_api():
  print ('Hello World Flask API')
  response = jsonify({'message': 'Hello from Query-Doc'})
  return response


# render landing page for uploading file and querying
@app.route('/')   
def main():   
  return render_template('index.html')  



# Upload PDF API
@app.route('/uploadpdf', methods=['POST'])
@cross_origin()
def uploadpdf():
  f = request.files['file'] 
  f.save(f.filename) 
  from indexify import IndexifyClient
  client = IndexifyClient()
  client.add_extraction_policy(extractor='tensorlake/pdf-extractor', name="pdf-extraction")
  client.add_extraction_policy(extractor='tensorlake/chunk-extractor', name="chunks", content_source="pdf-extraction", input_params={"chunk_size": 512, "overlap": 150})
  client.add_extraction_policy(extractor='tensorlake/minilm-l6', name="minilm-em", content_source="chunks")

  client.upload_file(path="f.filename")
  return jsonify({'message': 'uploaded'})



# Query PDF API
@app.route('/querypdf', methods=['POST'])
@cross_origin()
def querypdf():
  question_asked = request.form.get("query")
  from indexify import IndexifyClient
  client = IndexifyClient()

  from indexify_langchain import IndexifyRetriever
  params = {"name": "minilm-em.embedding", "top_k": 15}
  retriever = IndexifyRetriever(client=client, params=params)

  from langchain_core.output_parsers import StrOutputParser
  from langchain_core.prompts import ChatPromptTemplate
  from langchain_core.runnables import RunnablePassthrough
  # from langchain_openai import ChatOpenAI
  from langchain_google_vertexai import ChatVertexAI

  template = """Answer the question based only on the following context:
  {context}

  Question: {question}
  """
  prompt = ChatPromptTemplate.from_template(template)

  # model = ChatOpenAI(openai_api_key="<OpenAI API Key Goes Here>")
  model = ChatVertexAI()


  chain = (
      {"context": retriever, "question": RunnablePassthrough()}
      | prompt
      | model
      | StrOutputParser()
  )

  response = jsonify({'result': chain.invoke(question_asked)})
  return response




if __name__ == "__main__":
  app.run(debug=False, host="0.0.0.0", port=8080)

from typing import Any

from indexify.proto.executor_api_pb2 import (
    FunctionExecutorDescription,
    Task,
    TaskAllocation,
    TaskResult,
)


def function_executor_logger(
    function_executor_description: FunctionExecutorDescription, logger: Any
) -> Any:
    """Returns a logger bound with the FE's metadata.

    The function assumes that the FE might be invalid."""
    return logger.bind(
        fn_executor_id=(
            function_executor_description.id
            if function_executor_description.HasField("id")
            else None
        ),
        namespace=(
            function_executor_description.namespace
            if function_executor_description.HasField("namespace")
            else None
        ),
        graph=(
            function_executor_description.graph_name
            if function_executor_description.HasField("graph_name")
            else None
        ),
        graph_version=(
            function_executor_description.graph_version
            if function_executor_description.HasField("graph_version")
            else None
        ),
        fn=(
            function_executor_description.function_name
            if function_executor_description.HasField("function_name")
            else None
        ),
    )


def task_allocation_logger(task_allocation: TaskAllocation, logger: Any) -> Any:
    """Returns a logger for the given TaskAllocation.

    Doesn't assume that the supplied TaskAllocation is valid.
    """
    if task_allocation.HasField("task"):
        task: Task = task_allocation.task
        logger = logger.bind(
            task_id=task.id if task.HasField("id") else None,
            namespace=task.namespace if task.HasField("namespace") else None,
            graph=task.graph_name if task.HasField("graph_name") else None,
            graph_version=(
                task.graph_version if task.HasField("graph_version") else None
            ),
            fn=task.function_name if task.HasField("function_name") else None,
            invocation_id=(
                task.graph_invocation_id
                if task.HasField("graph_invocation_id")
                else None
            ),
        )
    return logger.bind(
        allocation_id=(
            task_allocation.allocation_id
            if task_allocation.HasField("allocation_id")
            else None
        ),
        fn_executor_id=(
            task_allocation.function_executor_id
            if task_allocation.HasField("function_executor_id")
            else None
        ),
    )


def task_result_logger(task_result: TaskResult, logger: Any) -> Any:
    """Returns a logger bound with the task result's metadata.

    The function assumes that the task result might be invalid."""
    return logger.bind(
        task_id=task_result.task_id if task_result.HasField("task_id") else None,
        allocation_id=(
            task_result.allocation_id if task_result.HasField("allocation_id") else None
        ),
        namespace=task_result.namespace if task_result.HasField("namespace") else None,
        graph=(task_result.graph_name if task_result.HasField("graph_name") else None),
        graph_version=(
            task_result.graph_version if task_result.HasField("graph_version") else None
        ),
        fn=(
            task_result.function_name if task_result.HasField("function_name") else None
        ),
        invocation_id=(
            task_result.graph_invocation_id
            if task_result.HasField("graph_invocation_id")
            else None
        ),
    )

from enum import Enum
from typing import List, Optional

from indexify.executor.function_executor.function_executor import (
    FunctionExecutor,
)
from indexify.proto.executor_api_pb2 import FunctionExecutorTerminationReason

from .task_allocation_info import TaskAllocationInfo


class EventType(Enum):
    FUNCTION_EXECUTOR_CREATED = 1
    FUNCTION_EXECUTOR_TERMINATED = 2
    SHUTDOWN_INITIATED = 3
    TASK_ALLOCATION_PREPARATION_FINISHED = 4
    SCHEDULE_TASK_ALLOCATION_EXECUTION = 5
    TASK_ALLOCATION_EXECUTION_FINISHED = 6
    TASK_ALLOCATION_FINALIZATION_FINISHED = 7


class BaseEvent:
    """
    Base class for events in the FunctionExecutorController.
    This class can be extended to create specific event types.
    """

    def __init__(self, event_type: EventType):
        self.event_type = event_type

    def __str__(self) -> str:
        return f"Event(type={self.event_type.name})"


class FunctionExecutorCreated(BaseEvent):
    """
    Event indicating that Function Executor got created or failed.

    The function_executor field is None if the function executor creation failed.
    In this case the fe_termination_reason field is set to the reason why.
    """

    def __init__(
        self,
        function_executor: Optional[FunctionExecutor],
        fe_termination_reason: FunctionExecutorTerminationReason | None,
    ):
        super().__init__(EventType.FUNCTION_EXECUTOR_CREATED)
        self.function_executor: Optional[FunctionExecutor] = function_executor
        self.fe_termination_reason: FunctionExecutorTerminationReason | None = (
            fe_termination_reason
        )


class FunctionExecutorTerminated(BaseEvent):
    """
    Event indicating that Function Executor has been terminated (destroyed).
    """

    def __init__(
        self,
        is_success: bool,
        fe_termination_reason: FunctionExecutorTerminationReason,
        allocation_ids_caused_termination: List[str],
    ):
        super().__init__(EventType.FUNCTION_EXECUTOR_TERMINATED)
        self.is_success: bool = is_success
        self.fe_termination_reason: FunctionExecutorTerminationReason = (
            fe_termination_reason
        )
        self.allocation_ids_caused_termination: List[str] = (
            allocation_ids_caused_termination
        )

    def __str__(self) -> str:
        return (
            f"Event(type={self.event_type.name}, "
            f"is_success={self.is_success}, "
            f"fe_termination_reason={FunctionExecutorTerminationReason.Name(self.fe_termination_reason)}, "
            f"allocation_ids_caused_termination={self.allocation_ids_caused_termination})"
        )


class ShutdownInitiated(BaseEvent):
    """
    Event indicating that Function Executor shutdown has been initiated.
    """

    def __init__(self):
        super().__init__(EventType.SHUTDOWN_INITIATED)


class TaskAllocationPreparationFinished(BaseEvent):
    """
    Event indicating that a task allocation has been prepared for execution or failed to do that.
    """

    def __init__(
        self,
        alloc_info: TaskAllocationInfo,
        is_success: bool,
    ):
        super().__init__(EventType.TASK_ALLOCATION_PREPARATION_FINISHED)
        self.alloc_info: TaskAllocationInfo = alloc_info
        self.is_success: bool = is_success

    def __str__(self) -> str:
        return (
            f"Event(type={self.event_type.name}, "
            f"task_id={self.alloc_info.allocation.task.id}, "
            f"allocation_id={self.alloc_info.allocation.allocation_id}), "
            f"is_success={self.is_success}"
        )


class ScheduleTaskAllocationExecution(BaseEvent):
    """
    Event indicating that a task allocation has been scheduled.
    """

    def __init__(self):
        super().__init__(EventType.SCHEDULE_TASK_ALLOCATION_EXECUTION)


class TaskAllocationExecutionFinished(BaseEvent):
    """
    Event indicating that a task allocation execution has been finished on Function Executor.
    """

    def __init__(
        self,
        alloc_info: TaskAllocationInfo,
        function_executor_termination_reason: FunctionExecutorTerminationReason,  # type: Optional[FunctionExecutorTerminationReason]
    ):
        super().__init__(EventType.TASK_ALLOCATION_EXECUTION_FINISHED)
        self.alloc_info: TaskAllocationInfo = alloc_info
        # Not None if the FE needs to get destroyed after running the task.
        self.function_executor_termination_reason = function_executor_termination_reason

    def __str__(self) -> str:
        function_executor_termination_reason_str: str = (
            "None"
            if self.function_executor_termination_reason is None
            else FunctionExecutorTerminationReason.Name(
                self.function_executor_termination_reason
            )
        )
        return (
            f"Event(type={self.event_type.name}, "
            f"task_id={self.alloc_info.allocation.task.id}, "
            f"allocation_id={self.alloc_info.allocation.allocation_id}), "
            f"function_executor_termination_reason={function_executor_termination_reason_str}"
        )


class TaskAllocationFinalizationFinished(BaseEvent):
    """
    Event indicating that a task allocation finalization is finished.
    """

    def __init__(self, alloc_info: TaskAllocationInfo, is_success: bool):
        super().__init__(EventType.TASK_ALLOCATION_FINALIZATION_FINISHED)
        self.alloc_info: TaskAllocationInfo = alloc_info
        self.is_success: bool = is_success

    def __str__(self) -> str:
        return (
            f"Event(type={self.event_type.name}, "
            f"task_id={self.alloc_info.allocation.task.id}, "
            f"allocation_id={self.alloc_info.allocation.allocation_id}), "
            f"is_success={self.is_success}"
        )

import asyncio
import time
from typing import Any

from indexify.executor.blob_store.blob_store import BLOBStore
from indexify.proto.executor_api_pb2 import (
    TaskFailureReason,
    TaskOutcomeCode,
)

from .events import TaskAllocationFinalizationFinished
from .metrics.finalize_task_allocation import (
    metric_task_allocation_finalization_errors,
    metric_task_allocation_finalization_latency,
    metric_task_allocation_finalizations,
    metric_task_allocations_finalizing,
)
from .task_allocation_info import TaskAllocationInfo
from .task_allocation_input import TaskAllocationInput
from .task_allocation_output import TaskAllocationOutput


async def finalize_task_allocation(
    task_alloc: TaskAllocationInfo, blob_store: BLOBStore, logger: Any
) -> TaskAllocationFinalizationFinished:
    """Prepares the task output for getting it reported to Server.

    The task output is either coming from a failed task or from its finished execution on the Function Executor.
    Doesn't raise any Exceptions.
    """
    logger = logger.bind(module=__name__)
    start_time = time.monotonic()

    with (
        metric_task_allocations_finalizing.track_inprogress(),
        metric_task_allocation_finalization_latency.time(),
        metric_task_allocation_finalization_errors.count_exceptions(),
    ):
        metric_task_allocation_finalizations.inc()
        try:
            await _finalize_task_alloc_output(
                alloc_info=task_alloc,
                blob_store=blob_store,
                logger=logger,
            )
            logger.info(
                "task allocation finalized",
                duration=time.monotonic() - start_time,
            )
            return TaskAllocationFinalizationFinished(
                alloc_info=task_alloc, is_success=True
            )
        except asyncio.CancelledError:
            return TaskAllocationFinalizationFinished(
                alloc_info=task_alloc, is_success=False
            )
        except BaseException as e:
            logger.error(
                "failed to finalize task allocation",
                exc_info=e,
                duration=time.monotonic() - start_time,
            )
            return TaskAllocationFinalizationFinished(
                alloc_info=task_alloc, is_success=False
            )


class _TaskAllocationOutputSummary:
    def __init__(self):
        self.output_count: int = 0
        self.output_bytes: int = 0
        self.invocation_error_output_count: int = 0
        self.invocation_error_output_bytes: int = 0
        self.next_functions_count: int = 0


async def _finalize_task_alloc_output(
    alloc_info: TaskAllocationInfo, blob_store: BLOBStore, logger: Any
) -> None:
    """Finalizes the task output.

    Raises exception on error."""
    if alloc_info.input is None:
        raise Exception(
            "task allocation input is None, this should never happen",
        )
    if alloc_info.output is None:
        raise Exception(
            "task allocation output is None, this should never happen",
        )

    input: TaskAllocationInput = alloc_info.input
    output: TaskAllocationOutput = alloc_info.output

    output_summary: _TaskAllocationOutputSummary = _task_output_summary(output)
    logger.info(
        "task allocation output summary",
        output_count=output_summary.output_count,
        output_bytes=output_summary.output_bytes,
        invocation_error_output_count=output_summary.invocation_error_output_count,
        invocation_error_output_bytes=output_summary.invocation_error_output_bytes,
        next_functions_count=output_summary.next_functions_count,
    )

    _log_function_metrics(output, logger)

    if output.outcome_code == TaskOutcomeCode.TASK_OUTCOME_CODE_SUCCESS:
        if len(output.uploaded_function_outputs_blob.chunks) == 0:
            # No output from function, usually means it returns None.
            await blob_store.abort_multipart_upload(
                uri=input.function_outputs_blob_uri,
                upload_id=input.function_outputs_blob_upload_id,
                logger=logger,
            )
        else:
            await blob_store.complete_multipart_upload(
                uri=input.function_outputs_blob_uri,
                upload_id=input.function_outputs_blob_upload_id,
                parts_etags=[
                    blob_chunk.etag
                    for blob_chunk in output.uploaded_function_outputs_blob.chunks
                ],
                logger=logger,
            )
        await blob_store.abort_multipart_upload(
            uri=input.invocation_error_blob_uri,
            upload_id=input.invocation_error_blob_upload_id,
            logger=logger,
        )
    elif output.outcome_code == TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE:
        await blob_store.abort_multipart_upload(
            uri=input.function_outputs_blob_uri,
            upload_id=input.function_outputs_blob_upload_id,
            logger=logger,
        )
        if (
            output.failure_reason
            == TaskFailureReason.TASK_FAILURE_REASON_INVOCATION_ERROR
        ) and len(output.uploaded_invocation_error_blob.chunks) != 0:
            await blob_store.complete_multipart_upload(
                uri=input.invocation_error_blob_uri,
                upload_id=input.invocation_error_blob_upload_id,
                parts_etags=[
                    blob_chunk.etag
                    for blob_chunk in output.uploaded_invocation_error_blob.chunks
                ],
                logger=logger,
            )
        else:
            await blob_store.abort_multipart_upload(
                uri=input.invocation_error_blob_uri,
                upload_id=input.invocation_error_blob_upload_id,
                logger=logger,
            )
    else:
        raise ValueError(
            f"Unexpected outcome code: {TaskOutcomeCode.Name(output.outcome_code)}"
        )


def _task_output_summary(
    task_output: TaskAllocationOutput,
) -> _TaskAllocationOutputSummary:
    summary: _TaskAllocationOutputSummary = _TaskAllocationOutputSummary()

    for output in task_output.function_outputs:
        summary.output_count += 1
        summary.output_bytes += output.manifest.size

    if task_output.invocation_error_output is not None:
        summary.invocation_error_output_count = 1
        summary.invocation_error_output_bytes = (
            task_output.invocation_error_output.manifest.size
        )

    summary.next_functions_count = len(task_output.next_functions)

    return summary


# Temporary workaround is logging customer metrics until we store them somewhere
# for future retrieval and processing.
def _log_function_metrics(output: TaskAllocationOutput, logger: Any):
    if output.metrics is None:
        return

    for counter_name, counter_value in output.metrics.counters.items():
        logger.info(
            "function_metric", counter_name=counter_name, counter_value=counter_value
        )
    for timer_name, timer_value in output.metrics.timers.items():
        logger.info("function_metric", timer_name=timer_name, timer_value=timer_value)

from typing import Any, Dict, List, Optional

from tensorlake.function_executor.proto.function_executor_pb2 import (
    BLOB,
    SerializedObjectInsideBLOB,
)

from indexify.proto.executor_api_pb2 import (
    FunctionExecutorTerminationReason,
    TaskAllocation,
    TaskFailureReason,
    TaskOutcomeCode,
)


class TaskAllocationMetrics:
    """Metrics for a task allocation."""

    def __init__(self, counters: Dict[str, int], timers: Dict[str, float]):
        self.counters = counters
        self.timers = timers


class TaskAllocationOutput:
    """Result of running a task allocation."""

    def __init__(
        self,
        allocation: TaskAllocation,
        outcome_code: TaskOutcomeCode,
        failure_reason: TaskFailureReason | None = None,
        function_outputs: List[SerializedObjectInsideBLOB] = [],
        uploaded_function_outputs_blob: Optional[BLOB] = None,
        invocation_error_output: Optional[SerializedObjectInsideBLOB] = None,
        uploaded_invocation_error_blob: Optional[BLOB] = None,
        next_functions: List[str] = [],
        metrics: Optional[TaskAllocationMetrics] = None,
        execution_start_time: Optional[float] = None,
        execution_end_time: Optional[float] = None,
    ):
        self.allocation = allocation
        self.outcome_code = outcome_code
        self.failure_reason = failure_reason
        self.function_outputs = function_outputs
        self.uploaded_function_outputs_blob = uploaded_function_outputs_blob
        self.invocation_error_output = invocation_error_output
        self.uploaded_invocation_error_blob = uploaded_invocation_error_blob
        self.next_functions = next_functions
        self.metrics = metrics
        self.execution_start_time = execution_start_time
        self.execution_end_time = execution_end_time

    @classmethod
    def internal_error(
        cls,
        allocation: TaskAllocation,
        execution_start_time: Optional[float],
        execution_end_time: Optional[float],
    ) -> "TaskAllocationOutput":
        """Creates a TaskAllocationOutput for an internal error."""
        return TaskAllocationOutput(
            allocation=allocation,
            outcome_code=TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE,
            failure_reason=TaskFailureReason.TASK_FAILURE_REASON_INTERNAL_ERROR,
            execution_start_time=execution_start_time,
            execution_end_time=execution_end_time,
        )

    @classmethod
    def function_timeout(
        cls,
        allocation: TaskAllocation,
        execution_start_time: Optional[float],
        execution_end_time: Optional[float],
    ) -> "TaskAllocationOutput":
        """Creates a TaskAllocationOutput for a function timeout error."""
        return TaskAllocationOutput(
            allocation=allocation,
            outcome_code=TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE,
            failure_reason=TaskFailureReason.TASK_FAILURE_REASON_FUNCTION_TIMEOUT,
            execution_start_time=execution_start_time,
            execution_end_time=execution_end_time,
        )

    @classmethod
    def function_executor_unresponsive(
        cls,
        allocation: TaskAllocation,
        execution_start_time: Optional[float],
        execution_end_time: Optional[float],
    ) -> "TaskAllocationOutput":
        """Creates a TaskAllocationOutput for an unresponsive FE aka grey failure."""
        # When FE is unresponsive we don't know exact cause of the failure.
        return TaskAllocationOutput(
            allocation=allocation,
            outcome_code=TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE,
            # Treat the grey failure as a function error and thus charge the customer.
            # This is to prevent service abuse by intentionally misbehaving functions.
            failure_reason=TaskFailureReason.TASK_FAILURE_REASON_FUNCTION_ERROR,
            execution_start_time=execution_start_time,
            execution_end_time=execution_end_time,
        )

    @classmethod
    def task_allocation_cancelled(
        cls,
        allocation: TaskAllocation,
        execution_start_time: Optional[float],
        execution_end_time: Optional[float],
    ) -> "TaskAllocationOutput":
        """Creates a TaskAllocationOutput for the case when task allocation didn't finish because its allocation was removed by Server."""
        return TaskAllocationOutput(
            allocation=allocation,
            outcome_code=TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE,
            failure_reason=TaskFailureReason.TASK_FAILURE_REASON_TASK_CANCELLED,
            execution_start_time=execution_start_time,
            execution_end_time=execution_end_time,
        )

    @classmethod
    def function_executor_terminated(
        cls,
        allocation: TaskAllocation,
    ) -> "TaskAllocationOutput":
        """Creates a TaskAllocationOutput for the case when task allocation didn't run because its FE terminated."""
        return TaskAllocationOutput(
            allocation=allocation,
            outcome_code=TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE,
            failure_reason=TaskFailureReason.TASK_FAILURE_REASON_FUNCTION_EXECUTOR_TERMINATED,
        )

    @classmethod
    def function_executor_startup_failed(
        cls,
        allocation: TaskAllocation,
        fe_termination_reason: FunctionExecutorTerminationReason,
        logger: Any,
    ) -> "TaskAllocationOutput":
        """Creates a TaskAllocationOutput for the case when we fail a task allocation that didn't run because its FE startup failed."""
        return TaskAllocationOutput(
            allocation=allocation,
            outcome_code=TaskOutcomeCode.TASK_OUTCOME_CODE_FAILURE,
            failure_reason=_fe_startup_failure_reason_to_task_failure_reason(
                fe_termination_reason, logger
            ),
        )


def _fe_startup_failure_reason_to_task_failure_reason(
    fe_termination_reason: FunctionExecutorTerminationReason, logger: Any
) -> TaskFailureReason:
    # Only need to check FE termination reasons happening on FE startup.
    if (
        fe_termination_reason
        == FunctionExecutorTerminationReason.FUNCTION_EXECUTOR_TERMINATION_REASON_STARTUP_FAILED_FUNCTION_ERROR
    ):
        return TaskFailureReason.TASK_FAILURE_REASON_FUNCTION_ERROR
    elif (
        fe_termination_reason
        == FunctionExecutorTerminationReason.FUNCTION_EXECUTOR_TERMINATION_REASON_STARTUP_FAILED_FUNCTION_TIMEOUT
    ):
        return TaskFailureReason.TASK_FAILURE_REASON_FUNCTION_TIMEOUT
    elif (
        fe_termination_reason
        == FunctionExecutorTerminationReason.FUNCTION_EXECUTOR_TERMINATION_REASON_STARTUP_FAILED_INTERNAL_ERROR
    ):
        return TaskFailureReason.TASK_FAILURE_REASON_INTERNAL_ERROR
    elif (
        fe_termination_reason
        == FunctionExecutorTerminationReason.FUNCTION_EXECUTOR_TERMINATION_REASON_FUNCTION_CANCELLED
    ):
        # This fe termination reason is used when FE gets deleted by Server from desired state while it's starting up.
        return TaskFailureReason.TASK_FAILURE_REASON_FUNCTION_EXECUTOR_TERMINATED
    else:
        logger.error(
            "unexpected function executor startup failure reason",
            fe_termination_reason=FunctionExecutorTerminationReason.Name(
                fe_termination_reason
            ),
        )
        return TaskFailureReason.TASK_FAILURE_REASON_INTERNAL_ERROR

import json
import logging
import os
from typing import Any, Dict, Generator, Iterator, List, Optional, Union

import httpx
from httpx_sse import ServerSentEvent, connect_sse
from pydantic import BaseModel, Field
from rich import print  # TODO: Migrate to use click.echo

from tensorlake.functions_sdk.data_objects import TensorlakeData
from tensorlake.functions_sdk.exceptions import (
    ApiException,
    GraphStillProcessing,
    RequestException,
)
from tensorlake.functions_sdk.graph import (
    ComputeGraphMetadata,
    Graph,
)
from tensorlake.functions_sdk.graph_serialization import (
    ZIPPED_GRAPH_CODE_CONTENT_TYPE,
    zip_graph_code,
)
from tensorlake.functions_sdk.object_serializer import get_serializer
from tensorlake.utils.http_client import (
    _TRANSIENT_HTTPX_ERRORS,
    get_httpx_client,
    get_sync_or_async_client,
)
from tensorlake.utils.retries import exponential_backoff

logger = logging.getLogger("tensorlake")


DEFAULT_SERVICE_URL = os.getenv("INDEXIFY_URL", "https://api.tensorlake.ai")


class GraphOutputMetadata(BaseModel):
    id: str
    num_outputs: int
    compute_fn: str


class RequestProgress(BaseModel):
    pending_tasks: int
    successful_tasks: int
    failed_tasks: int


class RequestError(BaseModel):
    function_name: str
    message: str


class ShallowRequestMetadata(BaseModel):
    id: str
    status: str
    outcome: str
    created_at: int


class Allocation(BaseModel):
    id: str
    server_id: str = Field(alias="executor_id")
    container_id: str = Field(alias="function_executor_id")
    created_at: int
    outcome: Optional[str] = None
    attempt_number: int


class Task(BaseModel):
    id: str
    status: str
    outcome: str
    created_at: int = Field(alias="creation_time_ns")
    allocations: Optional[List[Allocation]] = None


class RequestMetadata(BaseModel):
    id: str
    completed: bool
    status: str
    outcome: str
    failure_reason: str
    outstanding_tasks: int
    request_progress: dict[str, RequestProgress]
    graph_version: str
    created_at: str
    request_error: Optional[RequestError] = None
    outputs: List[GraphOutputMetadata] = []
    created_at: int


class RequestStartedEvent(BaseModel):
    request_id: str


class RequestFinishedEvent(BaseModel):
    request_id: str


class RequestProgressPayload(BaseModel):
    request_id: str
    fn_name: str
    task_id: str
    allocation_id: Optional[str] = None
    executor_id: Optional[str] = None
    outcome: Optional[str] = None


class WorkflowEvent(BaseModel):
    event_name: str
    stdout: Optional[str] = None
    stderr: Optional[str] = None
    payload: Union[RequestStartedEvent, RequestProgressPayload, RequestFinishedEvent]

    def __str__(self) -> str:
        stdout = (
            ""
            if self.stdout is None
            else f"[bold red]stdout[/bold red]: \n {self.stdout}\n"
        )
        stderr = (
            ""
            if self.stderr is None
            else f"[bold red]stderr[/bold red]: \n {self.stderr}\n"
        )

        return f"{stdout}{stderr}[bold green]{self.event_name}[/bold green]: {self.payload}"


def log_retries(e: BaseException, sleep_time: float, retries: int):
    print(
        f"Retrying after {sleep_time:.2f} seconds. Retry count: {retries}. Retryable exception: {e.__repr__()}"
    )


class TensorlakeClient:
    def __init__(
        self,
        service_url: str = DEFAULT_SERVICE_URL,  # service_url is already set from DEFAULT_SERVICE_URL, which reads from env var
        config_path: Optional[str] = None,
        namespace: str = "default",
        api_key: Optional[str] = None,
        **kwargs,
    ):
        self.service_url = service_url
        self._config_path = config_path
        self._client: httpx.Client = get_httpx_client(config_path)

        self.namespace: str = namespace
        self.compute_graphs: List[Graph] = []
        self.labels: dict = {}
        self._service_url = service_url
        self._timeout = kwargs.get("timeout")
        self._graphs: Dict[str, Graph] = {}
        self._api_key = api_key
        if not self._api_key:
            self._api_key = os.getenv("TENSORLAKE_API_KEY")

    def _request(self, method: str, **kwargs) -> httpx.Response:
        try:
            request = self._client.build_request(
                method, timeout=self._timeout, **kwargs
            )
            response = self._client.send(request)
            logger.debug(
                "Indexify: %r %r => %r",
                request,
                kwargs.get("data", {}),
                response,
            )
            status_code = response.status_code
            if status_code >= 400:
                raise ApiException(status_code=status_code, message=response.text)
        except httpx.RequestError as e:
            message = f"Make sure the server is running and accessible at {self._service_url}, {e}"
            raise ApiException(status_code=503, message=message)
        return response

    @classmethod
    def with_mtls(
        cls,
        cert_path: str,
        key_path: str,
        ca_bundle_path: Optional[str] = None,
        service_url: str = DEFAULT_SERVICE_URL,
        *args,
        **kwargs,
    ) -> "TensorlakeClient":
        """
        Create a client with mutual TLS authentication. Also enables HTTP/2,
        which is required for mTLS.
        NOTE: mTLS must be enabled on the Indexify service for this to work.

        :param cert_path: Path to the client certificate. Resolution handled by httpx.
        :param key_path: Path to the client key. Resolution handled by httpx.
        :param args: Arguments to pass to the httpx.Client constructor
        :param kwargs: Keyword arguments to pass to the httpx.Client constructor
        :return: A client with mTLS authentication

        Example usage:
        ```
        from indexify import IndexifyClient

        client = IndexifyClient.with_mtls(
            cert_path="/path/to/cert.pem",
            key_path="/path/to/key.pem",
        )
        assert client.heartbeat() == True
        ```
        """
        if not (cert_path and key_path):
            raise ValueError("Both cert and key must be provided for mTLS")

        client = get_sync_or_async_client(
            cert_path=cert_path, key_path=key_path, ca_bundle_path=ca_bundle_path
        )

        indexify_client = TensorlakeClient(service_url, *args, **kwargs)
        indexify_client._client = client
        return indexify_client

    def _add_api_key(self, kwargs):
        if self._api_key:
            if "headers" not in kwargs:
                kwargs["headers"] = {}
            kwargs["headers"]["Authorization"] = f"Bearer {self._api_key}"

    @exponential_backoff(
        max_retries=5,
        retryable_exceptions=(ApiException,),
        is_retryable=lambda e: isinstance(e, ApiException) and e.status_code == 503,
        on_retry=log_retries,
    )
    def _get(self, endpoint: str, **kwargs) -> httpx.Response:
        self._add_api_key(kwargs)
        return self._request("GET", url=f"{self._service_url}/{endpoint}", **kwargs)

    def _post(self, endpoint: str, **kwargs) -> httpx.Response:
        self._add_api_key(kwargs)
        return self._request("POST", url=f"{self._service_url}/{endpoint}", **kwargs)

    def _put(self, endpoint: str, **kwargs) -> httpx.Response:
        self._add_api_key(kwargs)
        return self._request("PUT", url=f"{self._service_url}/{endpoint}", **kwargs)

    def _delete(self, endpoint: str, **kwargs) -> httpx.Response:
        self._add_api_key(kwargs)
        return self._request("DELETE", url=f"{self._service_url}/{endpoint}", **kwargs)

    def _close(self):
        self._client.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self._close()

    def register_compute_graph(
        self,
        graph: Graph,
        code_dir_path: str,
        upgrade_tasks_to_latest_version: bool,
    ):
        graph_metadata: ComputeGraphMetadata = graph.definition()
        graph_code: bytes = zip_graph_code(graph=graph, code_dir_path=code_dir_path)
        response = self._post(
            f"v1/namespaces/{self.namespace}/compute-graphs",
            files={"code": graph_code},
            data={
                "compute_graph": graph_metadata.model_dump_json(exclude_none=True),
                "upgrade_tasks_to_latest_version": upgrade_tasks_to_latest_version,
                "code_content_type": ZIPPED_GRAPH_CODE_CONTENT_TYPE,
            },
        )
        response.raise_for_status()
        self._graphs[graph.name] = graph

    def delete_compute_graph(
        self,
        graph_name: str,
    ) -> None:
        """
        Deletes a graph and all of its invocations from the namespace.
        :param graph_name The name of the graph to delete.
        WARNING: This operation is irreversible.
        """
        response = self._delete(
            f"v1/namespaces/{self.namespace}/compute-graphs/{graph_name}",
        )
        response.raise_for_status()

    def tasks(self, graph: str, request_id: str) -> List[Task]:
        response = self._get(
            f"v1/namespaces/{self.namespace}/compute-graphs/{graph}/requests/{request_id}/tasks"
        )
        return [Task(**task) for task in response.json()["tasks"]]

    def graphs(self) -> List[ComputeGraphMetadata]:
        graphs_json = self._get(
            f"v1/namespaces/{self.namespace}/compute-graphs"
        ).json()["compute_graphs"]
        graphs = []
        for graph in graphs_json:
            graphs.append(ComputeGraphMetadata(**graph))

        return graphs

    def graph(self, name: str) -> ComputeGraphMetadata:
        response = self._get(f"v1/namespaces/{self.namespace}/compute-graphs/{name}")
        return ComputeGraphMetadata(**response.json())

    def logs(
        self, cg_name: str, invocation_id: str, allocation_id: str, file: str
    ) -> Optional[str]:
        try:
            response = self._get(
                f"namespaces/{self.namespace}/compute_graphs/{cg_name}/invocations/{invocation_id}/allocations/{allocation_id}/logs/{file}"
            )
            response.raise_for_status()
            return response.content.decode("utf-8")
        except ApiException as e:
            print(f"failed to fetch logs: {e}")
            return None

    def requests(self, graph: str) -> List[RequestMetadata]:
        response = self._get(
            f"v1/namespaces/{self.namespace}/compute-graphs/{graph}/requests"
        )
        requests: List[ShallowRequestMetadata] = []
        for request in response.json()["requests"]:
            requests.append(ShallowRequestMetadata(**request))

        return requests

    def request(self, graph: str, request_id: str) -> RequestMetadata:
        response = self._get(
            f"v1/namespaces/{self.namespace}/compute-graphs/{graph}/requests/{request_id}"
        )
        return RequestMetadata(**response.json())

    def call(
        self,
        graph: str,
        block_until_done: bool = False,
        input_encoding: str = "cloudpickle",
        **kwargs,
    ) -> str:
        if not block_until_done:
            return self._call(graph, input_encoding, **kwargs)
        events = self.call_stream(graph, input_encoding, **kwargs)
        try:
            while True:
                print(str(next(events)))
        except StopIteration as result:
            # TODO: Once we only support Python >= 3.13, we can just return events.close().
            events.close()
            return result.value

    def _call(
        self,
        graph: str,
        input_encoding: str = "cloudpickle",
        **kwargs,
    ) -> str:
        serializer = get_serializer(input_encoding)
        ser_input = serializer.serialize(kwargs)
        kwargs = {
            "headers": {
                "Content-Type": serializer.content_type,
                "Accept": "application/json",
            },
            "data": ser_input,
        }
        response = self._post(
            f"v1/namespaces/{self.namespace}/compute-graphs/{graph}",
            **kwargs,
        )
        return response.json()["request_id"]

    def call_stream(
        self,
        graph: str,
        input_encoding: str = "cloudpickle",
        **kwargs,
    ) -> Generator[WorkflowEvent, None, str]:
        serializer = get_serializer(input_encoding)
        ser_input = serializer.serialize(kwargs)
        kwargs = {
            "headers": {
                "Content-Type": serializer.content_type,
            },
            "data": ser_input,
        }
        self._add_api_key(kwargs)
        invocation_id: Optional[str] = None
        try:
            with connect_sse(
                self._client,
                "POST",
                f"{self.service_url}/v1/namespaces/{self.namespace}/compute-graphs/{graph}",
                **kwargs,
            ) as event_source:
                if not event_source.response.is_success:
                    resp = event_source.response.read().decode("utf-8")
                    raise Exception(f"failed to wait for invocation: {resp}")
                for sse in event_source.iter_sse():
                    for event in self._parse_invocation_events_from_sse_event(
                        graph, sse
                    ):
                        if invocation_id is None:
                            invocation_id = event.payload.request_id
                        yield event

        except _TRANSIENT_HTTPX_ERRORS:
            if invocation_id is None:
                print("invocation ID is unknown, cannot block until done")
                raise

            self.wait_on_invocation_completion(graph, invocation_id, **kwargs)

        if invocation_id is None:
            raise Exception("invocation ID not returned")

        return invocation_id

    def _parse_invocation_events_from_sse_event(
        self, graph: str, sse: ServerSentEvent
    ) -> Iterator[WorkflowEvent]:
        obj = json.loads(sse.data)

        for event_name, event_data in obj.items():
            # Handle bare ID events
            if event_name == "RequestStarted":
                yield WorkflowEvent(
                    event_name="RequestStarted",
                    payload=RequestStartedEvent(request_id=event_data["request_id"]),
                )
                continue

            # Handle RequestFinished events
            if event_name == "RequestFinished":
                yield WorkflowEvent(
                    event_name=event_name,
                    payload=RequestFinishedEvent(request_id=event_data["request_id"]),
                )
                continue

            # Handle all other event types
            event_payload = RequestProgressPayload.model_validate(event_data)
            event = WorkflowEvent(event_name=event_name, payload=event_payload)

            # Log failures with their stdout/stderr
            if (
                event.event_name == "TaskCompleted"
                and isinstance(event.payload, RequestProgressPayload)
                and event.payload.outcome == "failure"
            ):
                event.stdout = self.logs(
                    graph,
                    event.payload.request_id,
                    event.payload.allocation_id,
                    "stdout",
                )

                event.stderr = self.logs(
                    graph,
                    event.payload.request_id,
                    event.payload.allocation_id,
                    "stderr",
                )

            yield event

    @exponential_backoff(
        max_retries=10,
        retryable_exceptions=_TRANSIENT_HTTPX_ERRORS,
        on_retry=log_retries,
    )
    def wait_on_invocation_completion(
        self,
        graph: str,
        invocation_id: str,
        **kwargs,
    ):
        self._add_api_key(kwargs)
        with connect_sse(
            self._client,
            "GET",
            f"{self.service_url}/namespaces/{self.namespace}/compute_graphs/{graph}/invocations/{invocation_id}/wait",
            **kwargs,
        ) as event_source:
            if not event_source.response.is_success:
                resp = event_source.response.read().decode("utf-8")
                raise Exception(f"failed to wait for invocation: {resp}")
            for sse in event_source.iter_sse():
                events = self._parse_invocation_events_from_sse_event(graph, sse)
                for event in events:
                    if event.event_name == "InvocationFinished":
                        break

    def _download_outputs(
        self,
        graph: str,
        request_id: str,
        fn_name: str,
        output_metadata: GraphOutputMetadata,
    ) -> List[Any]:
        outputs = []
        for i in range(output_metadata.num_outputs):
            response = self._get(
                f"v1/namespaces/{self.namespace}/compute-graphs/{graph}/requests/{request_id}/output/{fn_name}/id/{output_metadata.id}/index/{i}",
            )
            response.raise_for_status()
            content_type = response.headers.get("Content-Type")
            if content_type == "application/json":
                encoding = "json"
            else:
                encoding = "cloudpickle"
            serializer = get_serializer(encoding)
            outputs.append(serializer.deserialize(response.content))
        return outputs

    def graph_outputs(
        self,
        graph: str,
        request_id: str,
        fn_name: str,
    ) -> List[Any]:
        """
        Returns the extracted objects by a graph for an ingested object. If the extractor name is provided, only the objects extracted by that extractor are returned.
        If the extractor name is not provided, all the extracted objects are returned for the input object.
        graph: str: The name of the graph
        invocation_id: str: The ID of the invocation.
        fn_name: Optional[str]: The name of the function whose output is to be returned if provided
        return: Union[Dict[str, List[Any]], List[Any]]: The extracted objects. If the extractor name is provided, the output is a list of extracted objects by the extractor. If the extractor name is not provided, the output is a dictionary with the extractor name as the key and the extracted objects as the value. If no objects are found, an empty list is returned.
        """
        response = self._get(
            f"v1/namespaces/{self.namespace}/compute-graphs/{graph}/requests/{request_id}",
        )
        response.raise_for_status()
        request = RequestMetadata(**response.json())
        if request.status in ["pending", "running"]:
            raise GraphStillProcessing()

        if request.request_error is not None:
            raise RequestException(request.request_error.message)

        all_outputs = []
        for output_metadata in request.outputs:
            if output_metadata.compute_fn == fn_name:
                all_outputs.extend(
                    self._download_outputs(graph, request_id, fn_name, output_metadata)
                )
        return all_outputs

import re
import numpy as np
from string import punctuation
from itertools import combinations
from utils.metrics_util import indexify_spans

ASPECT_IDX = 0
CATEGORY_IDX = 1
SENTIMENT_IDX = 2
OPINION_IDX = 3
IMPLICIT_IND_IDX = 4

IDX_LIST = [ASPECT_IDX, CATEGORY_IDX, SENTIMENT_IDX, OPINION_IDX, IMPLICIT_IND_IDX]
TERM_LIST = ["aspect", "category", "sentiment", "opinion", "implicit_indicator"]

NUM_SPANS = 2
SPAN_IDX = {ASPECT_IDX: 0, OPINION_IDX: 1}

def clean_punctuation(words):
    punc = re.compile(f"[{re.escape(punctuation)}]")
    words = punc.sub(" \\g<0> ", words)

    # remove extra spaces
    words = words.strip()
    words = " ".join(words.split())
    return words


def extract_spans_para(seq, seq_type, output_type, sentiment_dict={}, category_dict={}):
    quints = []
    sents = [s.strip() for s in seq.split("[SSEP]")]
    for s in sents:
        try:
            tok_list = ["[C]", "[S]", "[A]", "[O]", "[I]"]

            for tok in tok_list:
                if tok not in s:
                    s += " {} null".format(tok)
            index_ac = s.index("[C]")
            index_sp = s.index("[S]")
            index_at = s.index("[A]")
            index_ot = s.index("[O]")
            index_ie = s.index("[I]")

            combined_list = [index_ac, index_sp, index_at, index_ot, index_ie]
            arg_index_list = list(np.argsort(combined_list))

            result = []
            for i in range(len(combined_list)):
                start = combined_list[i] + 4
                sort_index = arg_index_list.index(i)
                if sort_index < 4:
                    next_ = arg_index_list[sort_index + 1]
                    re = s[start : combined_list[next_]]
                else:
                    re = s[start:]
                result.append(re.strip())

            ac, sp, at, ot, ie = result

            if output_type == "mvp":
                if at.lower() == "it":
                    at = "NULL"
                sp = sentiment_dict[sp]
                ac = category_dict[ac]

            at = clean_punctuation(at)
            ot = clean_punctuation(ot)

            if at.lower() == "null" or at.lower() == "implicit":
                at = "NULL"
            if ot.lower() == "null" or ot.lower() == "implicit":
                ot = "NULL"

            quints.append((at, ac.lower(), sp, ot, ie))

        except KeyError:
            ac, at, sp, ot, ie = "", "", "", "", ""
        except ValueError:
            try:
                print(f"In {seq_type} seq, cannot decode: {s}")
                pass
            except UnicodeEncodeError:
                print(f"In {seq_type} seq, a string cannot be decoded")
                pass
            ac, at, sp, ot, ie = "", "", "", "", ""

    return quints


def process_dataset(dataset):
    reviews = [x.split("####")[0] for x in dataset]

    raw_true_outputs = [eval(x.split("####")[1]) for x in dataset]
    true_outputs = []
    for output in raw_true_outputs:
        list_of_tuples = []
        for quint in output:
            if (
                quint[ASPECT_IDX].lower() == "null"
                or quint[ASPECT_IDX].lower() == "implicit"
            ):
                quint[ASPECT_IDX] = "NULL"
            if (
                quint[OPINION_IDX].lower() == "null"
                or quint[OPINION_IDX].lower() == "implicit"
            ):
                quint[OPINION_IDX] = "NULL"
            list_of_tuples.append(tuple(quint))
        true_outputs.append(list_of_tuples)
    return reviews, true_outputs


def accum_ea_eo_ia_io_sent(true_list, pred_list, accum_true=False, accum_pred=False):
    if accum_true:
        true_list[-1] += 1
    if accum_pred:
        pred_list[-1] += 1

def accum_span_len(span, true_list, pred_list, accum_true=False, accum_pred=False):
    length = len(span.split(" "))
    if accum_true:
        true_list.append(length)
    if accum_pred:
        pred_list.append(length)

def accum_polarities(polarities, pos, neg, neu):
    avg_polarities = []
    overall_polarities = []

    for pos_val, neg_val, neu_val in zip(pos, neg, neu):
        polarities.append(0)
        if pos_val > 0:
            polarities[-1] += 1
        if neg_val > 0:
            polarities[-1] += 1
        if neu_val > 0:
            polarities[-1] += 1

        total = neg_val + neu_val + pos_val
        avg_polarity = (neg_val * -1 + neu_val * 0 + pos_val * 1)/(total) if total != 0 else 0
        if avg_polarity > 0.33:
            overall_polarity = "pos"
        elif avg_polarity < -0.33:
            overall_polarity = "neg"
        else:
            overall_polarity = "neu"

        avg_polarities.append(avg_polarity)
        overall_polarities.append(overall_polarity)

    return avg_polarities, overall_polarities


def get_combos(tuple_len):
    combos = []
    for i in range(2, tuple_len):
        combos += list(combinations(IDX_LIST[:tuple_len], i))
    return combos


def indexify_outputs(reviews, outputs, idx):
    return [
        indexify_spans(annotation, review, idx)
        for review, annotation in zip(reviews, outputs)
    ]


def listify_outputs(outputs, idx):
    return [[quint[idx] for quint in annotation] for annotation in outputs]


def comboify_outputs(outputs, combo):
    new_outputs = []
    for annotation in outputs:
        new_annotation = []
        for quint in annotation:
            new_tuple = []
            for idx in combo:
                new_tuple.append(quint[idx])
            new_annotation.append(tuple(new_tuple))
        new_outputs.append(new_annotation)              
    return new_outputs


def get_precision_recall_fl_IoU(pred_outputs, true_outputs):
    n_tp, n_fp, n_fn, n_union = 0, 0, 0, 0
    num_empty = 0

    numerical_micro_IoU = []
    micro_IoU = []
    for i in range(len(pred_outputs)):
        pred_set = set(pred_outputs[i])
        true_set = set(true_outputs[i])

        num_intersection = len(pred_set & true_set)
        num_union = len(pred_set | true_set)

        n_tp += num_intersection
        n_union += num_union

        n_fp += len(pred_set - true_set)
        n_fn += len(true_set - pred_set)

        if len(pred_set) == 0 and len(true_set) == 0:
            num_empty += 1

            numerical_micro_IoU.append(0)
            micro_IoU.append(None)
        else:
            assert num_union != 0

            numerical_micro_IoU.append(float(num_intersection) / num_union)
            micro_IoU.append(float(num_intersection) / num_union)

    precision = float(n_tp) / (n_tp + n_fp) if n_tp + n_fp != 0 else 0
    recall = float(n_tp) / (n_tp + n_fn) if n_tp + n_fn != 0 else 0
    f1 = 2 * precision * recall / (precision + recall) if precision + recall != 0 else 0
    macro_IoU = float(n_tp) / n_union if n_union != 0 else 0
    avg_micro_IoU = (
        sum(numerical_micro_IoU) / (len(numerical_micro_IoU) - num_empty)
        if len(numerical_micro_IoU) - num_empty != 0
        else 0
    )
    return precision, recall, f1, macro_IoU, micro_IoU, avg_micro_IoU

# Built-in Imports
from typing import List

# Third-party libraries
import pandas as pd

# Internal imports
from main.sec import SECData
from utils._generic import indexify_url
from utils._requester import RateLimitedRequester
from utils._logger import MyLogger


class TickerData(SECData):
    """
    Inherited from SECData class. Retrieves data from SEC Edgar database based on ticker. Stores ticker data to be used in Scraper.

    url is constructed based on the following: https://www.sec.gov/Archives/edgar/data/{cik}/{ascension_number}/{file_name}

    cik is the CIK number of the company = access via get_ticker_cik

    ascension_number is the accessionNumber column of filings_df

    file name for xml is always '{ticker}-{reportDate}.{extension}
    """

    def __init__(
        self,
        ticker: str,
        requester_company: str = "Financial API",
        requester_name: str = "API Caller",
        requester_email: str = "apicaller@gmail.com",
        taxonomy: str = "us-gaap",
    ):
        super().__init__(
            taxonomy,
        )
        self._requester = RateLimitedRequester(
            requester_company=requester_company,
            requester_name=requester_name,
            requester_email=requester_email,
        )
        self.scrape_logger = MyLogger(name="TickerData").scrape_logger
        self.ticker = ticker.upper()
        self.cik = self.get_ticker_cik(self.ticker)
        self._submissions = self.get_submissions(self.cik)
        self._filings = None
        self._forms = None
        self._index = self.get_cik_index(self.cik)
        self._filing_folder_urls = None
        self._filing_urls = None

    @property
    def submissions(
        self,
    ) -> dict:
        if self._submissions is not None:
            self._submissions["cik"] = self.cik
            self._submissions["filings"] = self.filings.replace({pd.NaT: None}).to_dict(
                "records"
            )
        return self._submissions

    @property
    def filings(
        self,
    ) -> pd.DataFrame:
        if self._filings is None:
            self._filings = self._filings_as_df()
        return self._filings

    @property
    def filings_list(
        self,
    ) -> list:
        return self._filings_as_list()

    @property
    def latest_filing(
        self,
    ) -> pd.DataFrame:
        return self.filings.iloc[0, :].to_dict() if len(self.filings) > 0 else None

    @property
    def latest_10Q(
        self,
    ) -> dict:
        return (
            self.filings.query("form == '10-Q'").iloc[0, :].to_dict()
            if len(self.filings.query("form == '10-Q'")) > 0
            else None
        )

    @property
    def latest_10K(
        self,
    ) -> dict:
        return (
            self.filings.query("form == '10-K'").iloc[0, :].to_dict()
            if len(self.filings.query("form == '10-K'")) > 0
            else None
        )

    @property
    def latest_8K(
        self,
    ) -> dict:
        return (
            self.filings.query("form == '8-K'").iloc[0, :].to_dict()
            if len(self.filings.query("form == '8-K'")) > 0
            else None
        )

    @property
    def filing_folder_urls(
        self,
    ) -> list:
        if self._filing_folder_urls is None:
            self._filing_folder_urls = self._get_filing_folder_urls()
        return self._filing_folder_urls

    @property
    def filing_urls(
        self,
    ) -> list:
        if self._filing_urls is None:
            self._filing_urls = self.filings["file_url"].tolist()

        return self._filing_urls

    @property
    def forms(
        self,
    ) -> list:
        if self._forms is None:
            self._forms = list(set(self.filings["form"]))
            self._forms.sort()
        return self._forms

    def _get_filing_folder_urls(
        self,
    ) -> list:
        """Get filing folder urls from index dict.

        Args:
            index (dict): index dict from get_index method

        Returns:s
            filing_folder_urls (list): list of filing folder urls
        """

        filing_folder_urls = [
            self.BASE_SEC_URL + self._index["directory"]["name"] + "/" + folder["name"]
            for folder in self._index["directory"]["item"]
            if folder["type"] == "folder.gif"
        ]
        return filing_folder_urls

    def search_filings(
        self,
        form: str = None,
        start: str = None,
        end: str = None,
        **kwargs,
    ) -> List[dict]:
        """Search filings based on form, date, period.

        Args:
            form (str, optional): form to search for. Defaults to None.
            start or end (str, optional): date to search for. Defaults to None. Date format is 'YYYY-MM-DD' / 'YYYY-MM' / 'YYYY'
            **kwargs: additional keyword arguments can include any column in the filings DataFrame
        Returns:
            pd.DataFrame: DataFrame containing search results
        """
        query = []
        if form is not None:
            query.append(f"form == '{form.upper()}'")
        if start is not None:
            query.append(f"filingDate >= '{start}'")
        if end is not None:
            query.append(f"filingDate <= '{end}'")
        for key, value in kwargs.items():
            query.append(f"{key} == '{value}'")

        return self.filings.query(" and ".join(query)).to_dict("records")

    def get_filing_folder_index(self, folder_url: str, return_df: bool = True):
        """Get filing folder index from folder url.

        Args:
            folder_url (str): folder url to retrieve data from
            return_df (bool, optional): Whether to return a DataFrame or dict. Defaults to True.

        Returns:
            index (dict): index dict or dataframe
        """
        index_url = indexify_url(folder_url)
        index = self._requester.rate_limited_request(
            index_url, headers=self.sec_headers
        )
        return (
            pd.DataFrame(index.json()["directory"]["item"])
            if return_df
            else index.json()["directory"]["item"]
        )

    def _get_filings(
        self,
    ) -> dict:
        """Get filings and urls to .txt from submissions dict.

        Args:
            submissions (dict): submissions dict from get_submissions method

        Returns:
            filings (dict): dictionary containing filings
        """
        self.scrape_logger.info(f"Making http request for {self.ticker} filings...")
        filings = self._submissions["filings"]["recent"]

        if len(self._submissions["filings"]) > 1:
            self.scrape_logger.info(f"Additional filings found for {self.ticker}...")
            for file in self._submissions["filings"]["files"]:
                additional_filing = self.get_submissions(submission_file=file["name"])
                filings = {
                    key: filings[key] + additional_filing[key] for key in filings.keys()
                }
        return filings

    def _filings_as_df(
        self,
    ) -> pd.DataFrame:
        """Convert filings to DataFrame.

        Returns:
            pd.DataFrame: filings as DataFrame
        """
        filings = pd.DataFrame(self._get_filings())
        # Convert reportDate, filingDate, acceptanceDateTime columns to datetime
        filings["reportDate"] = pd.to_datetime(filings["reportDate"])
        filings["filingDate"] = pd.to_datetime(filings["filingDate"])
        filings["acceptanceDateTime"] = pd.to_datetime(filings["acceptanceDateTime"])
        filings["cik"] = self.cik

        filings = filings.loc[~pd.isnull(filings["reportDate"])]

        # get folder url for each row
        filings["folder_url"] = (
            self.BASE_DIRECTORY_URL
            + self.cik
            + "/"
            + filings["accessionNumber"].str.replace("-", "")
        )

        # get file url for each row
        filings["file_url"] = (
            filings["folder_url"] + "/" + filings["accessionNumber"] + ".txt"
        )

        return filings

    def _filings_as_list(
        self,
    ) -> list:
        """Get filings as list of dictionaries.

        Returns:
            list: list of filings as dictionaries
        """
        return self.filings.to_dict("records")

    def __repr__(self) -> str:
        class_name = type(self).__name__
        # main_attrs = ['ticker', 'cik', 'submissions', 'filings']
        # available_methods = [method_name for method_name in dir(self) if callable(
        #     getattr(self, method_name)) and not method_name.startswith("_")]
        return f"""{class_name}({self.ticker})
    CIK: {self.cik}
    Latest filing: {self.latest_filing['filingDate'].strftime('%Y-%m-%d') if self.latest_filing else 'No filing found'} for Form {self.latest_filing['form'] if self.latest_filing else None}. Access via: {self.latest_filing['folder_url'] if self.latest_filing else None}
    Latest 10-Q: {self.latest_10Q['filingDate'].strftime('%Y-%m-%d') if self.latest_10Q else 'No filing found'}. Access via: {self.latest_10Q['folder_url'] if self.latest_10Q else None}
    Latest 10-K: {self.latest_10K['filingDate'].strftime('%Y-%m-%d') if self.latest_10K else 'No filing found'}. Access via: {self.latest_10K['folder_url'] if self.latest_10K else None}"""

    def __repr_html__(self) -> str:
        # class_name = type(self).__name__
        # main_attrs = ['ticker', 'cik', 'submissions', 'filings']
        # available_methods = [method_name for method_name in dir(self) if callable(
        #     getattr(self, method_name)) and not method_name.startswith("_")]
        latest_filing_date = (
            self.latest_filing["filingDate"].strftime("%Y-%m-%d")
            if self.latest_filing
            else "No filing found"
        )
        latest_filing_form = self.latest_filing["form"] if self.latest_filing else None
        latest_filing_folder_url = (
            self.latest_filing["folder_url"] if self.latest_filing else None
        )
        latest_10Q_date = (
            self.latest_10Q["filingDate"].strftime("%Y-%m-%d")
            if self.latest_10Q
            else "No filing found"
        )
        latest_10Q_folder_url = (
            self.latest_10Q["folder_url"] if self.latest_10Q else None
        )
        latest_10K_date = (
            self.latest_10K["filingDate"].strftime("%Y-%m-%d")
            if self.latest_10K
            else "No filing found"
        )
        latest_10K_folder_url = (
            self.latest_10K["folder_url"] if self.latest_10K else None
        )
        return f"""
        <div style="border: 1px solid #ccc; padding: 10px; margin: 10px;">
            <h3>{self.submissions['name']}</h3>
            <h5>{self.submissions['sicDescription']}</h5>
            <p><strong>Ticker:</strong> {self.ticker}</p>
            <p><strong>CIK:</strong> {self.cik}</p>
            <p><strong>Latest filing:</strong> {latest_filing_date} for Form {latest_filing_form}. Access via: <a href="{latest_filing_folder_url}">{latest_filing_folder_url}</a></p>
            <p><strong>Latest 10-Q:</strong> {latest_10Q_date}. Access via: <a href="{latest_10Q_folder_url}">{latest_10Q_folder_url}</a></p>
            <p><strong>Latest 10-K:</strong> {latest_10K_date}. Access via: <a href="{latest_10K_folder_url}">{latest_10K_folder_url}</a></p>
        </div>
        """

